INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1320447-ise402', 'stk-user2352', 'ISE 402', 'info', '{"desc": "رابعًا: توجد بعض النماذج المعدلة من هذا النموذج والتي تناسب وجود تخفيضات في السعر عند شراء\nكميات كبيرة وعملية التوريد التدريجية وغيرها مما سنناقشه لاحقًا إن شاء الله\nخامسا: يمكنك أن تلاحظ أن ثيات زمن التقد يجعل الحسابات بسيطة والتحكم في المخزون يسيرا. قد يتصور\nالبعض أن ثبات زمن التقدم أو زمن التوريد هو من الأمور المستحيلة وأنه من طبيعة الأمور ان يكون\nمتغيرا. ولكن في الحقيقة فإنه يمكننا تثبيت زمن التقدم بل وتقليله ببعض المجهود في اختيار الموردين وبناء\nعلاقات طويلة الأمد معهم والتركيز على هذا المطلب. بالطبع ليس معنى ثبات زمن التقدم ألا يختلف أبدا\nولكنه قد يتغير بمقدار بسيط مثل 5% أو 10 % فقط.\nتقدير تكلفة التخزين والتوريد\nلكي نستخدم هذا النموذج فإننا نحتاج لتقدير تكلفة التخزين السنوية للوحدة وكذلك تكلفة كل أمر توريد\n(طلبية). تعرضت في المقالة السابقة لشرح هذه التكاليف ولكنني أوجزها هنا مرة أخرى\nتشمل تكلفة تجميد رأس المال بمعنى Annual Holding Cost تكلفة التخزين أو تكلفة الاحتفاظ بالمخزون\nعدم استثماره وكذلك تكلفة هلاك نسبة من المخزون وتكلفة الأنظمة والعمالة والأرض والمعدات المستخدمة\nلحفظ المخزون. فتكلفة تجميد رأس المال تساوي نسبة العائد المتوقع لو استثمرنا ثمن هذا المخزون وهذه\nتختلف حسب العائد الذي نتوقعه من المشاريع التي نستثمر فيها فقد تكون 15 % أو 20 % بمعنى أن تكلفة\n1000 جنيه من المخزون من ناحية تجميد رأس المال تساوي 150 أو 200 جنيه. أما تكلفة هلاك نسبة من\nالمخزون فيمكن تقديرها حسب سابق الخبرة فقد تجد أن نسبة 1% او 5% تهلك أو تصبح عديمة القيمة\nسنويا وبالتالي نضيف هذه التكلفة. يمكننا حساب كل تكاليف العمالة والمعدات والإيجار وخلافه وتحويلها\nلنسبة من قيمة المخزون. وبتجميع كل هذه التكاليف نحصل على تكلفة التخزين. وبالتالي يمكننا أن نحدد هذه\n.% التكلفة كنسبة من ثمن الوحدة من المادة المخزنة مثل أن تكون 20 % أو 25 % أو 30\nيجب الانتباه إلى أن تكلفة العمالة المقصود بها تكلفة العمالة المرتبطة بتخزين هذه المواد فلا تقم بتحميل\nمرتبات كل عمالة المخازن على مادة واحدة وإنما يتم تحميل جزء منها يتناسب مع نسبة هذه المادة للمواد\nالأخرى. بالطبع يوجد بعض التقدير أو التقريب وقد نتجادل في أن العمالة موجودة في كافة الاحوال وأن\nمخزون هذه المادة لو قل فلن يتم الاستغناء عن العمالة. عموما فغن تكلفة العمالة المرتبطة بالمادة المخزنة\nوحدها تكون قليلة بالنسبة لباقي التكاليف. نفس الأمر قد تناقشه عند تقدير إيجار الأرض أو المخازن فإن كنا\nسندفعها في جميع الأحوال فيمكن اعتبار أنها غير مؤثرة لأنها لن تتغير. ولكن يمكن أن نجادل أيضا بأننا لوقمنا بتقلسل المخزون من كل المواد فقد نفكر في استئجار مخزن آخر وفي استغلال العمالة الزائدة في عمل\nآخر.\nبصفة عامة فإن تكلفة الاحتفاظ بالمخزون تتراوح عادة بين 15 % و 25 % وذلك لأن المكون الرئيسي لهذه\nالتكلفة هو تكلفة تجميد رأس المال وهذه عادة تكون أعلى بقليل من عائد البنوك لأننا لن نستثمر في مشروع\nإلا إذا كان عائده أعلى من عائد البنوك.نسبة هلاك المخزون تختلف حسب نوعية المخزون وحسب مدة\nتخزينه فهي تكون قليلة مثل 1% في معظم الأحيان سوى في بعض المواد التي تفسد سريعا أو المنتجات التي\nتقادم بسرعة. تكلفة المخازن والعمالة تكون عادة نسبة بسيطة مثل 3% أو 5% من تكلفة المواد المخزنة.\nوبالتالي فإن تكلفة الاحتفاظ بالمخزون تكون عادة ما بين 15 % إلى 25 % ولكن لا يمنع هذا أن تكون أعلى\nأو أقل في بعض الحالات\nتشمل مصاريف النقل والتأمين والمصاريف الإدارية Order cost تكلفة الطلبية أو أمر التوريد الواحد\nلإعداد المواصفات وأمر التوريد والتناقش مع الموردين وتكلفة فتح اعتماد وتكلفة الفحص وغير ذلك. هذه\nيجب تقديرها للوصول إلى قيمتها الحقيقية.\nماذا عن التصنيع الداخلي؟\nفي شرحنا سابقا اعتمدنا على أننا سنشتري هذه المادة او المنتج من مورد خارجي ولكن ماذا إذا كنا نقومبتصنيع هذه المادة او الجزء بأنفسنا؟ إن نفس هذا النموذج يستخدم مع الأخذ في الاعتبار أن تكلفة الطلبية\nالواحدة ستختلف لأنها ستشمل تكلفة تضبيط الماكينات لإنتاج هذه المادة أو المنتج بالإضافة إلى أي تكلفة\nإدارة أخرى لإعداد أمر الشغل وما شابه. فيماعدا ذلك فإن كل ماذكر ينطبق على حالة التصنيع الداخلي\nحجم الطلبية الاقتصادي عند وجود تخفيضات في الكمية\nفي مقالة سابقة وأُحب أن أضيف بعض الحالات الأكثر EOQ ناقشت نموذج حجم الطلبية الاقتصادي أو\nتعقيدا في هذه المقالة. في كثيرٍ من الأحيان يعرض علينا المورد تخفيضا عند شراء كميات كبيرة فمثلا يكون\nسعر القطعة ريالين في حالة شراء 1000 قطعة ويكون السعر ريال ونصف في حالة شراء 3000 قطعة.\nالسبب في ذلك هو أن التكلفة التي يتحملها المورد تقل عند شراء كمية كبيرة وذلك قد يكون بسبب أن خط\nالإنتاج يتم تضبيطه خصيصا لإنتاج القطع المطلوبة وبالتالي فإن تكلفة وقت التضبيط يتم تحميلها على عدد\nالقطع المنتجة وقد يكون بسبب توفر مخزون كبير لدى المورد ويريد التخلص منه وغير ذلك من فوائد\nوفورات الحجم الكبير. ما يعنينا هنا هو كيف نحدد حجم الطلبية الاقتصادي بالنسبة لنا كمشترين\nكيفية تحديد حجم الطلبية الأمثل في هذه الحالة؟\nأولا: نستخدم نموذج حجم الطلبية الأمثل مع كل سعر من الأسعار المعروضة. اختلاف السعر سيؤثر على\nالمقام وهو تكلفة التخزين السنوية، لماذا؟ لأن تكلفة التخزين السنوية للوحدة عادة تكون نسبة من قيمة وحدة\nالمخزون (أي قيمة القطعة أو الكيلو جرام او المتر…) فمثلا تساوي 20 % من قيمة وحدة المخزون\nثانيا: في حالة أن حجم الطلبية الذي نحصل عليه في كل حالة يقع في مدى الكمية التي ينطبق عليها السعر\nفإننا ناخذ هذه القيمة في الاعتبار. ولكن سنلاحظ أن بعض القيم تكون أقل من مدى الكمية التي ينطبق عليها\nهذا السعر. بمعنى أننا نحسب حجم الطلبية عند سعر الوحدة 5 جنيهات مثلا وهو السعر الذي سيتقاضاه\nالمورد في حالة شراء عدد من 700 إلى 1200 قطعة، فنجد أن ناتج النموذج هو 540 قطعة وهو أقل من\n700 وبالتالي فهو حل مرفوض. في هذه الحالة نأخذ أقرب قيمة تجعل الكمية تقع في المدى الذي ينطبق\nعليه السعر وهو في هذا المثال 700 قطعة. أما لو كان ناتج النموذج هو 830 - مثلا- فإننا نقبله كما هو\nلأنه في المدى الصحيح. بذلك نحصل على عدة نقاط مرشحة لكي تكون حجم الطلبية الاقتصادي\n11\nثالثا: للاختيار بين هذه الكميات التي حصلنا عليها من الخطوة السابقة فإننا نحسب التكلفة الكلية عند كل من\nهذه الكميات. ولكن في هذا النوع من المسائل فإننا نضيف تكلفة الشراء إلى التكلفة الكلية بمعنى ان التكلفة\nالكلية يتم حسابها هكذا\nالتكلفة السنوية الكلية = تكلفة الشراء + تكلفة التخزين السنوية + تكلفة التوريد السنوية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-402-production-systems-and-inventory-control/120945/11", "user": "user2352", "ts": 1390002347000, "tid": 120945, "pn": 11}}', 1390002347000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450457-ise402', 'stk-fahad_2012', 'ISE 402', 'info', '{"desc": "الـ 402 تعتبر من اهم كورسات التخصص\nالمادة تتكلم عن التحكم بالمخزن وطرق التنبأ والتحكم بالانتاج\nالمادة تحتاج دكتور شريح لها مثل الدكتور بن داية\n\nجودة المقرر بشكل عام : ممتازة\n\nالمواضيع التي يغطيها المقرر : Forecasting Methods , Production Planning , Inventory management\n\nالكتاب المستخدم للمقرر : واضح و ممتاز\n\nالأسئلة والأمثلة المستخدمة في المقرر : متنوعة ومفيدة في تثبيت الشرح\n\nسيلبس المادة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-402-production-systems-and-inventory-control/120945/12", "user": "Fahad_2012", "ts": 1464247244000, "tid": 120945, "pn": 12}}', 1464247244000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466857-ise402', 'stk-user8581', 'ISE 402', 'info', '{"desc": "بقيمها كطالب CISE لأن فهد وصانع القرار ماقصروا شرحوا مواضيع الكورس وأهميته بالنسبة للاندستريال :\n\n- الكورس بالنسبة لي أعتبره متوسط : أسهل من ISE 205 و أصعب من ISE 307\n- حاول تنزل مع دكتور شرحه ممتاز على سبيل المثال مع Dr.Mohamed darghouth لأن راح يسهل عليك أشياء كثيرة و يختصر عليك الوقت .\n- أسئلة الهومورك مهمة في فهم الكورس , حاول تحلها بنفسك واذا كنت مضطر إنقلها لكن انقل بفهم .\n- تقدر تطلع منها بقريد طيب لكن الموضوع يحتاج جهد مثل أي كورس , فلا تستهين بالكورس وتقرأ السلايدات وتشوف حلول الاسئلة بسيطة . حاول تحل بيدك وتحل بالخطوات لأن المياجر أغلب الأسئلة فيها written ونفس الوقت لاتهمل الجانب النظري مثل ( عدد , عرف , اشرح و … )\n- ممكن بعض الأشياء تكون جديدة عليك لأنك cise وبقية السكشن لأنهم اندستريال يكونوا عارفينها , فإذا مافهمت شيئ اسئل الدكتور عنها عشان لايجيب في الكويزات أو المياجر أشياء متعلقة بكورسات ثانية انت ماخذتها .\n- الكورس بيكون فيه سكشنين فموضوع القريدات يعتمد على درجات السكشن الثاني وغالبا ً بيكون أفرج .\n- الفاينل مب كومبريهنسف .\n\nملفات مهمة للكورس ( ise zalt ) ومن ضمها كويزات دارغوث\n402 - Google Drive\n\nبالتوفيق وفالكم الـ A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-402-production-systems-and-inventory-control/120945/13", "user": "user8581", "ts": 1485197715000, "tid": 120945, "pn": 13}}', 1485197715000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1537337-ise402', 'stk-user12137', 'ISE 402', 'info', '{"desc": "T232\n\nجودة المقرر بشكل عام:\n\nالمقرر مهم وممتاز جدا ومستوى صعوبته (متوسط مائل إلى الصعوبة)، لكن للأسف أحسه عام بزيادة، بحيث ما تم الإشارة لطريقة التعامل مع بعض الحالات الشاذة المتكررة على أرض الواقع؛ فصار نظري أكثر من أنه عملي (يمكن نتوسع أكثر في ISE470&472), وغير كذا يعلموك بعض التكنيكات الي ما منها فائدة ومستحيل تستفيد منها بالواقع، وهم يقولوا لك ذلك وهم يعلموك اياها… وأيضا المفروض يكون نظام التوزيع هوموركات وليس كويزات، لأن تتعامل مع داتا كثيرة والقروثيم طويلة، لو كان بالاكسل شيت او البايثون أريح وأفيد\n\nالمواضيع التي يغطيها المقرر:\n\nذكروها الشباب فوق بكامل التفاصيل ولا قصروا، بس أهم شيء هو ال inventory control, forecasting methods, production planning هذي أهم ثلاث مواضيع من وجهة نظري بالكورس\n\nالكتاب المستخدم للمقرر:\n\nكتاب نامياس الإصدار السابع، ما قرأته ولكن الحنبلي طايح مدح بالكاتب ويشيد به بقوة\n\nالأسئلة والأمثلة المستخدمة في المقرر:\n\nدرستها عند الحنبلي، الأمثلة المستخدمة ممتازة ولكن تفتقد للتفاصيل الواقعية، لكن الأسئلة من الكتاب بسلايدات الحنبلي يكون فيها تفاصيل أحيانا\n\nمدى فائدته في الناحية التطبيقية:\n\nمفيدة جدا، وهي حجر الأساس للسبلاي تشين اذا مهتم تكمل فيه؛ فشد حيلك فيها\n\nإضافات:\n\nالاختبارات:\nنزلناها بترم عاصف والحنبلي\nميجر 1 (true false، mcq, written) : الميجر 1 على تشابتر 1 و2 و3، الآفرج كان 33 من 45 وأنا جبت 39.5\nميجر 2 (true false، mcq, written) : الميجر 2 على تشابتر 4، الآفرج كان 30.7 من 45 وأنا جبت 37.8\nالفاينل (true false، mcq, written) : الفاينل على تشابتر 5 و8، وملغم أسئلة من كويزات درغوث، أنصح بقوة بالرجوع لها قبل الحل، تلقوها بنيبولا، الآفرج كان 22.1 من 30 وأنا جبت 28\n\nطريقة مذاكرتي:\n-أركز مع الدكتور في الكلاس\n-اقرأ سلايدات باعبيد للفهم (اذا في وقت)\n-أحل من مسائل سلايدات الحنبلي\n-أحل كويزات الدرغوث\n\nطلعت بA الحمدلله, ولولا أني ما تعديت ال3 غيابات المجانية من الحنبلي, يمكن جبت A+, بس الله يوفقنا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-402-production-systems-and-inventory-control/120945/16", "user": "user12137", "ts": 1717452282000, "tid": 120945, "pn": 16}}', 1717452282000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1269876-ise402', 'stk-user9409', 'ISE 402', 'info', '{"desc": "و عليكم السلام و الرحمة\n\nتقريباً اسألته كانت في البداية مشاهبة أو مطابقة لأسئلة الكتاب بس كان يغير فكرة في السؤال احياناً سهالات و أحياناً ما تدري وش يبغى 😐\n\nبس اسلوبه في الفاينل تغير … جاب اسألة شوي متعمقة بسبب ان الفاينل كان كومبرهنسف\n\nبشكل عام إذا انت فاهم المادة أسألته بتكون متوسطة إلى سهلة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-402/149824/7", "user": "user9409", "ts": 1380512715000, "tid": 149824, "pn": 7}}', 1380512715000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1446835-ise402', 'stk-hussain_ali93', 'ISE 402', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nأنا احد طلاب الـcise آخذ هذا الكورس في هذا السمستر،\nكانت عندي فكرة إن المادة سهلة بشكل عام، وتوزيع الدرجات ستاندارد،\nلكن تفاجأت بالوضع الحالي، أفرج المياجر قريب من ال50% ( أنا حوالي الأفرج)\nكيف تتوقعون بيكون القريدات ، عطونا من خبرتكم ياخوان =_=", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-402/172996/1", "user": "Hussain_Ali93", "ts": 1460839524000, "tid": 172996, "pn": 1}}', 1460839524000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1435116-ise402', 'stk-loseit1997', 'ISE 402', 'info', '{"desc": "الدكتور بن دايه يهتم بالفهم العميق والتمرس في مايقول ولكن الحق يقال متعمق في الكورس والسبلاي شين\nاذا بتأخذ معاه ركز على الدرايف ومش راح يجيب أسئلة دايركت الامامندر يعني راح يفهمك الأساسيات وانت عليك تبدع اذكر في الماستر اخذت معاه 508 وكان يشرح المودل الموجود بشكل معمق ولكن في الاختبار يطلب منك تطبيق الي قاله على مودل ثاني.\nبالنسبة لي مزاجتية والمعتمدة على مستوى الطلاب في الكورس هي مايعيبة.\nالدرجات في العادة سي وسي بلس والمتميز بي وبي بلس والأيه للفلته.\nيكرف في البرزنتيشن ويخلي الطلاب تشرح الأجزاء الخفيفة من المادة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-402/170875/5", "user": "loseit1997", "ts": 1449004077000, "tid": 170875, "pn": 5}}', 1449004077000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-royalty-ise402', 'stk-royalty', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f98286", "n": "Dr. Hesham K. Alfares", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه ise 402 ترم 122\n\nبنود التقييم :\n\nالتحضير :\nعليه %5 ويحضر كل محاضرة ويخصم على الغياب والتأخير\n\nطريقة الشرح :\nعنده نوت على الوورد يفتحه ويشرح منه , ويستخدم السبورة في حل المسائل\n\nالكويزات :\nأعطانا 4 كوزات وأخذ أفضل 3 ، كل كوز %5 ومن الشرح … بالنسبة لي سهلة\n\nالمياجر:\n25% ميجر 1/ كان سهل والأفرج عالي\n25% ميجر 2/ سهل لكن طويل والوقت مايكفي\n\nالفاينلات :\nعليه %30 والاختبار غير شامل ، وكان سهل\n\nالقريد النهائي:\nأعطيه +a\n\nالصوت:\nواضح\n\nإضافات :\nانحشرت بالجدول ونزلت معه , وانصدمت صراحة من الكلام اللي بالمنتدى لأنه غير الواقع … الدكتور محترم ويعطيك حقك وشرحه زين واختباراته على شرحه … ميزة أخرى وهي السرعة في رصد الدرجات سريييع … مشكلته بالحياة الجوال إذا دق وانت في المحاضرة طوالي يسحبه ويحطه بجيبه ولكن للأمانة في بداية كل محاضرة يقول صمتوا جوالاتكم ويطلع جواله ويصمته وعاد مشكلتك اذا دق جوالك …\n\nأخيرا هذا رأيي الشخصي في الدكتور في هذي المادة وقد يكون تعامله مختلف في مواد أخرى\nوفقنا الله وإياكم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1228939-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hesham-k-alfares/98286/18", "user": "Royalty", "ts": 1369685749000, "tid": 98286, "pn": 18}}]}', 1369685749000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2536-ise402', 'stk-user2536', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f98638", "n": "Dr. Abdulbasit Andijani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ise 402\n\nالتحضير : يحضر كل محاضرة بالقروب\n\nطريقة الشرح : متمكن جدا من المادة وكانت أجمل كورس اخذته في القسم\n\nالكويزات : كثيرة ومتعبة لانه يجي معها هووم ورك وتسليم وورك شوب في نفس اليوم لكن سهلة خصوصا مع تصحيح القريدر الممتاز\n\nالمياجر والفاينلات : مثل ماهو معروف … نص الاختبار نسخ من الاختبارات القديمة …\n\nالقريد النهائي: A+++++++++++++\n\nالصوت: واضح\n\nإضافات : صحيح الكورس متعب لكن أكثر من رااائع\nوالدكتور اندجاني من افضل الدكاترة في القسم ان لم يكن افضلهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p744551-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulbasit-andijani/98638/2", "user": "user2536", "ts": 1292405290000, "tid": 98638, "pn": 2}}]}', 1292405290000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2352-ise402', 'stk-user2352', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f98638", "n": "Dr. Abdulbasit Andijani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 402 - Production Systems and Inventory Control\n\nهذه المادة يا شباب الاندستريال مهم جداً و المادة “رائعة”\n\nما أقول سهلة ولا صعبة ، لكنها مهمة جدًا لتخصصنا كـ ISE\n\nوهي تقريبًا لب التخصص ، وأنصحكم تدرسوها مع أنديجاني … لكنها معاه أبدًا مش سهلة ، يبغالها أنك تعطيها حقها من الشغل ، وحيتعبكم شوية بالبروكتات والبرزنتيشن وكيس ستدي ، بس على كلام الشباب ما يندموا أبدًا أنهم أخذوها معه ، خصوصًا أنه دكتور معروف لدى القطاع الخاص في المملكة،،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p785612-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulbasit-andijani/98638/3", "user": "user2352", "ts": 1297353742000, "tid": 98638, "pn": 3}}]}', 1297353742000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_phenom-ise402', 'stk-the_phenom', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f98638", "n": "Dr. Abdulbasit Andijani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 402 - Term 132\n\nالتحضير :\nاول ما يدخل و هو عادة يتأخر خمس الى عشر دقائق\nويقول اذا قفلت ملف التحضير فلا احد يراجعني لأنه غايب 😁\n\nطريقة الشرح :\n\nرائع جدا بالنسبة لي 👍\nيشرح على سلايدات\nو غالبا شرحه يعتمد على تجاربه الخاصة لما كان يشتغل 👍 👍\nويحاول يربط المادة العلمية بالواقع العملي وطريقته أروع لما يخلي الطلاب يربطوا المادة بالوورك شوب الاسبوعي فيخليهم يعيشون الجو العملي بأنفسهم 🤴 🤴\n\nالكويزات :\nسهلة و من الكويزات القديمة او الاختبارات وحتى السلايدات تكفي 🚬 🚬\n\nالمياجر:\nسهلة لكن طويــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــلة 😲\nمع انه محذر من الموضوع بس كلم نفسك بتنصدم يعني بتنصدم 😆 😆\nغالبا اختباراته من الهومورك و من الاولد اكزام الموجود بالجمعية\nو التصحيح عسل حد الدعسة 🥊 🥊 🥊\nالفاينلات :\nنفس نظام المياجر\nبالسهولة و الطول 😁\n\nالقريد النهائي:\n\nA\n🤴 🤴\n\nالصوت:\nواضح\n\nإضافات :\nحاول تنزل معاه اي كورس\nشؤيح و ذو خبرة طويلة\nخفيف دم و راعي نكتة ❤️ ❤️\nمن أفضل المدرسين اللي مروا علي بصراحة و فرصة رائعة للمهندس الصناعي ان يدرس معاه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373153-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulbasit-andijani/98638/11", "user": "THE_PHENOM", "ts": 1401271476000, "tid": 98638, "pn": 11}}]}', 1401271476000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hmdturki-ise402', 'stk-hmdturki', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f98639", "n": "Dr. Mohammed Ben Daya", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ise 402\n\nالتحضير مزاجي ولكن متوقع منك إنك تحضر كل كلاس لأن كل إسبوع فيه كويز وهومورك(ما عدا أسابيع المياجر)\n\nطريقة الشرح: سلايدات ويوزع هاندوتس وأوراق لأمثلة يحلها بالكلاس ويحل أحيانا أمثلة من الكتاب ويعتمد على الإكسل بحل بعض الأمثلة, ينوع ما راح تمل معه لكنك راح تتعب بالنقل وكتابة الملاحظات. أسئلته على العكس من كل الكورسات السابقة هو ما راح يختبر قدرتك على إدارة الوقت والحل بسرعة ولكنه يختبر فهمك للمسائل والمفاهيم هذه شبه قاعدة عنده.\n\nالمياجر: اكتب معه نوتس واحضر كل كلاس وتذكر أسئلة الكويز وحاول تفهم الديرافيشن افهمها واذا ما قدرت احفظ لأنه ما يمزح اذا قال راح تجي.\n\nأعتقد إنه من أهم دكاترة القسم وفيه كلام إنه راح يمشي والصراحة إن مشى القسم ماله قيمة, راح يكون فقيدة الرجل. عموما اللي يتاح له يدرس كورس معه قبل يمشي من طلاب التخصص لا يفوته هذا شيخ ودكتور فاهم وشرحه عظيم.\n\nالقسم إن فقده فالصراحة ما بقى دكاترة كويسين, والله يعين الدفعات الجاية, مستوى الشرح عند البقية سيء إلا من رحم ربي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1446927-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-ben-daya/98639/26", "user": "HmdTurki", "ts": 1460941222000, "tid": 98639, "pn": 26}}]}', 1460941222000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisalovic-ise402', 'stk-faisalovic', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f152977", "n": "Dr. Ismail Almaraj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE-402- TERM-202 (Online)\n\nالتحضير :\n\nعن طريق اكسل شيت قبل نهاية الكلاس بدقيقة ومايدقق على التأخير ابد\n\nطريقة الشرح :\n\nعن طريق سلايداته يقراها ويشرح ولما يكون يحتاج يوضح زيادة يستخدم القلم الإلكتروني، شرحه يمشي الحال مع انه يسوي كل اللي عليه لتوصيل المعلومه،ويستقبل الأسئله بصدر رحب مهما كانت مكرره او تافهه، اصلا الماده سهله وما تحتاج شرح يكفيك قراءة السلايدات.\n\nالكويزات :\n\nالكويزات نفس افكار الهومورك ويكون مستواها متوسط، الصعوبة تكون من ناحية قلة الوقت نوعاً ما، لكن جزء الكونسبشوال صعب وما ادري من فين يجي، للجزء الرياضي يكفيك اسئلة السلايدات والهوموررك لكن للكونسبشوال حاول تركز على الكتاب.\nالمياجر:\n\nكان فيه ميد واحد عليه 25% وكان جلد وصلخ وحرايق وهو اللي كتبه\n\nالفاينلات :\n\nكان عليه 35% وتقريبا نفس مستوى الميد لكن اسهل نوعا ما + حذف الماتريال القديم\n\nالقريد النهائي:\n\nالدكتور الله يرزقه الجنه عطاني فوق حقي بقريدين ما ادري بالغلط او هو رفعنا، لكن ما اذكر احد كان زعلان على توزيع القريدات، + الماده كانت ستاندر لكنه خلاها افرج عشان يرفعنا وبيض الله وجهه، ياليت الدكاتره الثانين ياخذون جزء بسيط من سماحته وأخلاقه.\n\nالصوت:\n\nالشرح انجليزي ونادر ما يتكلم عربي وكلامه واضح ومفهوم\n\nإضافات :\n\nالدكتور قامه في حسن التعامل و الأخلاق، متفهم دائما لوضع الطالب ويبحث عن مصلحته، الله يوفقه ويستر عليه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530063-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ismail-almaraj/152977/5", "user": "FAISALOVIC", "ts": 1621752165000, "tid": 152977, "pn": 5}}]}', 1621752165000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-ise402', 'stk-user8581', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f172117", "n": "Dr. Mohamed Darghouth", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 402 - Term 161\n\nالتحضير : شديد في التحضير خاصة في بداية السمستر ويتنرفز من التأخير ( ما ألومه في بعض الحالات ) . ينادي بالأسماء بداية الكلاس و أتوقع إنه يمسح بعض الغيابات لو كلمته لأن كان معانا واحد من الشباب الله يذكره بالخير أغلب السمستر متأخر أو غايب .\n\nطريقة الشرح : شرحه بالنسبة لي أشوفه ممتاز , يمكن مقارنة بالدكتور الثاني ( بيرم ) . يشرح من السلايدات و يحل الأسئلة مع الطلاب .\nأفضل شيئ فيه هو يوزع هانداوت ويجبرك تحله وبعد مايعطيكم 5 دقايق , يحل الاسئلة الي في الهانداوت مع الطلاب و اذا عندك سؤال اسئل وهو ماراح يقصر لكن إنتبه تسأله سؤال هو توه مجاوب عليه !\n\nالكويزات : 6 كويزات أغلبها متوسطة مائلة للسهولة وحذف أسوء كويز . طبعا الكويزات مشابة للكويزات الموجودة في ise zalt ( الرابط موجود في نهاية الرد )\nتقريبا ً كل اسبوعين كويز + هومورك .\n\nالمياجر:\nالميجر الأول : الماتيريال كان سهل لكن الوقت قصير ( تقريبا ساعة ونص ) والاسئلة طويلة عددها 5 على ما أظن و كلها written فأنتبه لنقطة الوقت .\nفيه درس linear programming راح يقول لكم داخل في الميجر لكن ما راح يجيب منه شيئ .\nالميجر الثاني :الماتيريال كان اصعب نوعاً ما والوقت كافي ( ساعتين ) الاسئلة كلها ريتين . فيه سؤال كان من الهومورك فلا تسحب على الهومورك أو تنقلها من السلوشن بدون فهم !\nالفاينل : الماتيريال سهل لكن الوقت نوعا ما ً قصير ( ساعتين وتالي عطانا ربع ساعة زيادة ) يحتاج تدرب وتحل بوقت قصيرة .\n\nملاحظة مهمة : في الكويزات والمياجر والفاينل لاتهمل الأجزاء النظرية ! ترا يجيب منها , لا تستغرب يعطيك سؤال عدد أو اشرح أو عرف ! في الفاينل مثلا تقريبا ً صفحة ونص كانت الأسئلة فيها نظرية . صحيح الكورس يوحي لك إن الأسئلة بتكون حسابات لكن مع د.درغوث الوضع مختلف . لاتسحب على اي شيئ\n\nالقريد النهائي: كشرح أعطيه B+ لكن كتعامل الصراحة صعبة تحكم لأن أول ماتقابله راح تحكم عليه إنه حساس و يتنرفز من أبسط الأشياء لكن مع نهاية السمستر و اذا رحت له المكتب تكتشف إن عصبيته هي من حرصه على مصلحة الطلاب .\n\nالصوت: واضح ولهجته تونسية .\n\nإضافات :\n- يتنرفز من الجوال بشكل غير طبيعي . إذا دخل الكلاس حتى لو مابدأ الشرح لاتطلع الجوال أو تخليه على الطاولة يعني بإختصار لا تخليه يشوف الجوال حتى لو تحت الكرسي !\n- هو شباب وطيب , إذا تبي تكسبه حاول تشارك معاه في الكلاس وإذا سأل جاوب . كلما كان كلاسكم فعال كلما تساهل معكم وصار حبيب ومع الوقت راح يأخذ ويعطي معاكم .\n- إذا أفرج السكشن في الميجر الأول كان أعلى من أفرج السكشن الثاني يعطيكم بونص ونفس الشي مع الفاينل والميجر الثاني .\n- في التصحيح دقيق خاصة في الأسئلة النظرية ( عدد , عرف , اشرح و … )\n- لاتحكم عليه من أول كلاس أو من موقف , صحيح أحيانا يعصب أو يتنرفز لكن هو يبي مصلحتك فطول بالك .\n- الهوموركات ماعليها شيئ في السلاباس لكن هو يحسبها ضمن درجات الـحضور .\n- فيه برزنتيشن على نهاية السمستر( عن الـ JIT & MRP ) البرزنتيشن مب موجود في توزيع الدرجات على ما أظن فأعتقد هو بمثابة البونص أو على أساس مستواك فيه يزيدك .\n- في المياجر والكويزات خل حلك واضح + حل خطوة بخطوة .\n- كان فيه هومورك على Linear Programming وتستخدم برنامج Lindo اسمه على ما أظن . اسئل شباب الاندستريال لو ماعرفت تحل الهومورك .\n- الفاينل مب كومبريهنسف .\n\nالقريدات :\nكان معانا سكشن ثاني فما علمنا وش راح يكون نظام القريدات : افرج أو ستنادرد .\nلكن هذي درجاتي وطلعت بـ B+\n\n35 - 40 الميجر الأول\n32 - 40 الميجر الثاني\nالكويزات تقريبا ً فل مارك\nالفاينل 31.5 - 41\nالحضور + الهوموركات : فل مارك .\n\nالمجموع تقريبا 150 من 181 !\n\nشرحه بالنسبة لي كاف لكن يحتاج تدرب كثير وتحل مسائل عشان تتعود عليها + تتعود على الوقت لأن الاسئلة يصير حلها طويل كلما تتقدم في المنهج خاصة في الفاينل .\nولولا ظروف معينة صارت لي قبل لفاينل أتوقع الـ A كانت شبه مضمونة لكن الحمدلله على كل حال .\n\n- ملفات للـ للكورس ومن ضمنها الكويزات .\nDr. Mohammed Darghouth - Google Drive\n\n- أنصح طلاب الـ CISE بأنهم ينزلوا مع الدكتور .\n\nبالتوفيق يا شباب وفالكم الـ A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466862-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-darghouth/172117/6", "user": "user8581", "ts": 1485200594000, "tid": 172117, "pn": 6}}]}', 1485200594000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkd-ise402', 'stk-mkd', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f172117", "n": "Dr. Mohamed Darghouth", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر والمادة: ISE 402 – Term 172\n\nالتعامل: مزاجي جدا، يوم أحسن دكتور ويوم ماله خلق يشوف وجهك. لا تسال أسئلة بديهية اذا شفته بالمزاج الثاني لإنه بيزبد لك قدام العالم. خلك منتبه لمزاجه عشان ما تحط نفسك بموقف شين\n\nالصوت: واضح\n\nالشرح: بال402 شريح لابعد درجة، أتوقع افضل دكتور 402 بشكل عام من ناحية توصيل المعلومة. يعطي هاند اوت ( زي أوراق العمل ) تحلونها داخل الكلاس تخليك تفهم مضبوط بحيث انك اذا جيت تذاكر للمياجر ولا للكويزات تبدا تذاكر من الملفات اللي يحطها بالبلاكبورد بتعدين تراجع ذيك الاوراق\n\nالتحضير: يوميا بداية الكلاس ينادي بالاسماء ، شديد بالتحضير. بداية السمستر يشدد عالتاخير لكن شوي شوي يبدا يلين ولو تجي متأخر شويتين ما يعصب. حاول تجي بدري دايم مب عشان التحضير لكن عشان المادة نفسها لانها جدا مهمة لطلاب الISE.\n\nالتصحيح: عادي جدا يعطيك حقك\n\nالمياجر والفاينل (الاختبارات بشكل عام): كانت كومن مع عبدالعال وعطيه، ما كانت شينة لكن الوقت كان جدا ضيق والاسئلة طويلة وتحتاج تحسب بسرعة من غير حاسبه اذا تبي تمشي سريع سريع بالاسئلة.\n\nإضافات: باختصار : الدكتور مزاجي صعب تراجعه بالتصحيح لكن شريح درجة أولى ويطلعك فاهم واذا عطيت مادته حقها بتطلع بقريد ممتاز ان شاء الله اذا غضيت طرفك عن المشاكل اللي ذكرناها فوق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504894-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-darghouth/172117/9", "user": "MKD", "ts": 1547468765000, "tid": 172117, "pn": 9}}]}', 1547468765000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10932-ise402', 'stk-user10932', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f172117", "n": "Dr. Mohamed Darghouth", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 402 ، ترم كورونا (192) نصه حضوري والنص ثاني عن بعد ( مافيه اختلاف كبير بين الحضوري ويوم درسنا عن بعد في النقاط اللي بذكرها ) .\n\nالتحضير : الدكتور شديد في التحضير وأحياناً يعاتب اللي يتأخرون .\nطريقة الشرح : يفتح سلايدات ويشرح منها ، ودائماً يوزع هاند آوت ( مهمة جداً ) للطلاب وكل واحد يحل لحاله ، وبعدها يسألنا عنها ونحلها سوا .\nالكويزات : اتوقع من اول كلاس وزع علينا اوراق فيها جميع تواريخ الكويزات والمياجر ، الكويزات اشوفها سهله اذا انت مركز معاه بالشرح ، وأحيانا يجيب اسئلة كونسبت .\nالمياجر: المياجر نفس الحكاية ، ركز مع شرحه وافهم الهاند آوت واسئلة الهوموورك صح وأضمن لك أعلى من 90% في الميجر .\nالفاينلات : نفس مستوى المياجر تقريباً او اسهل ، بحكم اننا اختبرنا الفاينل قبل ترم 201 بسبب الحوسة اللي صارت بسبب كورونا ( الله يبعده عنا ويكفينا شره ونرجع للكلاسات ) .\nالقريد النهائي: ++++++A وبجدارة .\nالصوت: واضح وممتاز .\nإضافات : الدكتور منظم جداً وشريح درجة أولى ، اعتبره عراب الـ 402 بلا منازع ، دائما يعطي جو في الكلاس ويحمس الطلاب للمشاركة والحل ويخليك تفهم المادة غصب . اذا حصلت لك الفرصة تنزل معه 402 لا تتردد ، المادة حرفيا مادة قريد معه الله يسعده ويوفقه وين ماراح .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525322-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-darghouth/172117/11", "user": "user10932", "ts": 1599073915000, "tid": 172117, "pn": 11}}]}', 1599073915000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-ise402', 'stk-bader_alqahtani', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f172117", "n": "Dr. Mohamed Darghouth", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE402-202 online\nالتحضير : يحضر نهاية المحاضرة دايما و الرجال ما يهمه التحضير قد ان الطالب يستفيد من المحاضرة اعتقد ما كان يحضر الا لان الجامعة جابرته يحضر .\nطريقة الشرح :شرحه صراحة رايق يشرح الكونسبت كويس و يعيد و يزيد وما يسلك في الشرح يهمه الطالب يطلع فاهم طبعا في البداية يشرح الكونسبت بشكل رايق بعدها يشرح الامثلة و يحل مع الطلاب و يخليهم يشاركون معه و جدا شرحه كويس كنت اركز في شرحه و الشي ذا خلا وقت مذاكرتي قليلة لان اغلب الاشياء شرحها و الحلو انه يحل معك الامثلة خطوة خطوة و يشجع الطلاب يحلون معه\nالكويزات :الكوزات طبعا فيها جزء نظري و جزء مسائل و في الاون لاين المسائل كانت املاء فراغ و الصراحة كنت انصدم من الدرجة لما اشوف السليوشن اتوقع شيء سيء و يطلع معطي بارشال عليه لو غيره يحسبه صفر و يراعي في الشي ذا لكن كوزاته تحتاج تكون مذاكر الكونسبت لان بيجي عليه كذالك المسائل تحتاج تكون مذاكر\nالمد:صراحة كان صعب و الوقت ما كفانا بحكم الاون لاين و الاسئلة كانت اصعب من الكوزات بسبب ان الي كان يكتبها الكوردنيتر\nالفاينلات :كان اسهل من المد بس لازال فيه صعوبة و كثير خبصوا\nالقريد النهائي:B+\nالصوت:واضح جذا\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529848-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-darghouth/172117/12", "user": "Bader_Alqahtani", "ts": 1620251196000, "tid": 172117, "pn": 12}}]}', 1620251196000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-order-ise402', 'stk-order', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f176914", "n": "Dr. Ahmed Attia", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "171-Ise402\nالمدرس غالبا مايحضر الا نادر جدا … شرحه اشوفه انه ممتاز ومناسب لي (امكن يختلف بكورسات ثانيه)، تصحيحه ياخوان عسل عسل عسل مرات حلي وحل خويي يختلف كامل وكلنا ناخذ يجيبها من اسئلة الكتاب .\nانصحه فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492384-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-attia/176914/2", "user": "Order", "ts": 1526338043000, "tid": 176914, "pn": 2}}]}', 1526338043000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-orientation14-ise402', 'stk-orientation14', 'ISE 402', 'doc', '{"docs": [{"id": "stk-dr-f176914", "n": "Dr. Ahmed Attia", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 402 - 182\nالتحضير : نادر لكن اذا حضر فيكون بداية المحاضرة.\nطريقة الشرح : مرتبة. يراجع لك اللي اخذت اخر كلاس و يشرح الاشياء المهمة وطريقة الحل بالتفصيل\nالكويزات : سهلة وتصحيحه على الفكرة اكثر من الناتج النهائي.\nالمياجر و الفاينلات: كومن بالنسبة لي سهلة لكن لازم تنتبه للوقت. معظم الطلاب يشتكون ان الوقت قصير.\nالقريد النهائي: ِA++++\nالصوت: واضح و لهجة مصرية واضحة\nإضافات : ياليت كل الدكاترة يملكون نصف أخلاقه على الأقل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509254-ise402", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-attia/176914/5", "user": "orientation14", "ts": 1556726553000, "tid": 176914, "pn": 5}}]}', 1556726553000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
